export const escapeHtml = (value: string): string => value.replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]!);

// Human labels for the export impact explanation. The lists come straight from
// the archive builder's declared data classes so the visible "what is / is not
// included" copy cannot drift from what the export actually reads.
const humanizeDataClass = (value: string): string => value.split('_').map(part => part.charAt(0).toUpperCase() + part.slice(1)).join(' ');
const exportRetainedItems = WORKSPACE_EXPORT_RETAINED_DATA_CLASSES.map(name => `<li>${humanizeDataClass(name)}</li>`).join('');
const exportExcludedItems = WORKSPACE_EXPORT_EXCLUDED_SECRET_CLASSES.map(name => `<li>${humanizeDataClass(name)}</li>`).join('');

